  const sieve = new Array(2001).fill(true); sieve[0] = sieve[1] = false;
  for (let i = 2; i * i <= 2000; i++) if (sieve[i]) for (let j = i * i; j <= 2000; j += i) sieve[j] = false;
  for (let n = 0; n <= 2000; n++) assert.equal(isPrime(n), sieve[n], String(n));
